const instagram = String($json.instagram_status || '').toUpperCase();
const facebook = String($json.facebook_status || '').toUpperCase();
const retryCount = Number($json.retry_count || 0);

let status;

if (
  instagram === 'POSTED' &&
  facebook === 'POSTED'
) {
  status = 'POSTED';
} else if (
  retryCount >= 5 &&
  (
    instagram === 'FAILED' ||
    facebook === 'FAILED'
  )
) {
  status = 'FAILED';
} else {
  status = 'PROCESSING';
}

return {
  json: {
    id: $json.id,
    instagram_status: instagram,
    facebook_status: facebook,
    status,
    retry_count: retryCount
  }
};

const data = $json;

const existingStatus = String(
  $('Google Sheets • Mark Processing').item.json.facebook_status || ''
).toUpperCase();

const failed = !!data.error;

let facebookStatus;

if (existingStatus === 'POSTED' && !data.error) {
  facebookStatus = 'POSTED';
} else {
  facebookStatus = failed ? 'FAILED' : 'POSTED';
}

return {
  json: {
    id: $('Google Sheets • Mark Processing').item.json.id,
    facebook_status: facebookStatus
  }
};

const data = $json;

const existingStatus = String(
  $('Google Sheets • Mark Processing').item.json.instagram_status || ''
).toUpperCase();

const failed =
  !!data.error ||
  data.status_code === 'ERROR' ||
  data.status_code === 'EXPIRED';

let instagramStatus;

if (existingStatus === 'POSTED' && !data.error) {
  instagramStatus = 'POSTED';
} else {
  instagramStatus = failed ? 'FAILED' : 'POSTED';
}

return {
  json: {
    id: $('Google Sheets • Mark Processing').item.json.id,
    instagram_status: instagramStatus
  }
};

const instagram = String($json.instagram_status || 'PENDING').toUpperCase();
const facebook = String($json.facebook_status || 'PENDING').toUpperCase();

const currentRetryCount = Number($json.retry_count || 0);

return {
  json: {
    ...$json,
    status: 'PROCESSING',
    instagram_status: instagram === 'POSTED' ? 'POSTED' : 'PROCESSING',
    facebook_status: facebook === 'POSTED' ? 'POSTED' : 'PROCESSING',
    retry_count: currentRetryCount + 1
  }
};
